private final Semaphore soapSlots = new Semaphore(50);

@RunOnVirtualThread
@GET @Path("/reports/settlement/{day}")
public Report settlement(@PathParam("day") String day) throws InterruptedException {
    soapSlots.acquire();                             // 1. respect the downstream's limit
    try {
        return soapClient.settlementFor(day);        // 2. blocks: parks the virtual thread
    } finally {
        soapSlots.release();
    }
}

